LANGUAGE sql
STABLE
SECURITY INVOKER
AS $$
    SELECT COALESCE(
        (
            
            SELECT rbac_context->'_' ? '_'
            FROM (
                SELECT auth.f_0065()->'_' AS rbac_context
            ) jwt_data
            WHERE rbac_context IS NOT NULL
        ),
