CREATE OR REPLACE FUNCTION audit.f_0066()
RETURNS TRIGGER AS $$
DECLARE
    v_recorded_at TIMESTAMPTZ;
    v_record_id UUID;
    v_old_value JSONB;
    v_new_value JSONB;
    v_entity_id UUID;
    v_secret TEXT;
    v_signature TEXT;
    v_payload TEXT;
BEGIN
    v_recorded_at := now();
    v_record_id := COALESCE((NEW).id, (OLD).id);

    v_old_value := CASE
        WHEN TG_OP IN ('_', '_') THEN to_jsonb(OLD)
    END;

    v_new_value := CASE
        WHEN TG_OP IN ('_', '_') THEN to_jsonb(NEW)
    END;

    v_entity_id := audit.f_0086(
        TG_TABLE_NAME,
        COALESCE(v_new_value, v_old_value)
    );

    SELECT value INTO v_secret FROM audit.t_0046 WHERE key = '_';
    IF v_secret IS NULL THEN
        RAISE EXCEPTION '_';
    END IF;

    v_payload := jsonb_build_object(
        '_', auth.f_0100(),
        '_', v_recorded_at,
        '_', TG_TABLE_SCHEMA || '_' || TG_TABLE_NAME,
        '_', v_record_id,
        '_', TG_OP,
        '_', v_old_value,
        '_', v_new_value,
        '_', v_entity_id,
        '_', current_setting('_', true)
    )::text;

    v_signature := encode(
        extensions.hmac(v_payload, v_secret, '_'),
        '_'
    );

    INSERT INTO audit.log (
        c_0389, p_0123, c_0488, c_0487, c_0388,
        c_0332, c_0331, c_0321, c_0385,
        c_0440, con_0119
    ) VALUES (
        v_recorded_at,
        auth.f_0100(),
        TG_TABLE_SCHEMA,
        TG_TABLE_NAME,
        v_record_id,
        TG_OP,
        v_old_value,
        v_new_value,
        current_setting('_', true),
        v_signature,
        v_entity_id
    );

    RETURN COALESCE(NEW, OLD);
END;
$$ LANGUAGE plpgsql SECURITY DEFINER
   SET search_path = '_';




CREATE OR REPLACE FUNCTION audit.f_0076()
RETURNS TRIGGER AS $$
BEGIN
    RAISE EXCEPTION '_%_%_%_', TG_OP, TG_TABLE_SCHEMA, TG_TABLE_NAME;
END;
$$ LANGUAGE plpgsql
   SET search_path = '_';





CREATE OR REPLACE FUNCTION audit.f_0086(
    p_0107 TEXT,
    p_0082 JSONB
) RETURNS UUID AS $$
DECLARE
    c_0409 UUID;
BEGIN
    CASE p_0107
        WHEN '_' THEN
            c_0409 := (p_0082->>'_')::UUID;

        WHEN '_' THEN
            c_0409 := (p_0082->>'_')::UUID;

        WHEN '_' THEN
            SELECT f."c_0171" INTO c_0409
            FROM mrv."t_0012" f
            WHERE f."c_0353" = (p_0082->>'_')::UUID;

        WHEN '_', '_' THEN
            SELECT f."c_0171" INTO c_0409
            FROM mrv."t_0012" f
            WHERE f.id = (p_0082->>'_')::UUID;

        WHEN '_' THEN
            SELECT f."c_0171" INTO c_0409
            FROM mrv."t_0012" f
            JOIN mrv."t_0006" c ON c."c_0186" = f.id
            WHERE c.id = (p_0082->>'_')::UUID;

        WHEN '_' THEN
            c_0409 := (p_0082->>'_')::UUID;

        WHEN '_' THEN
            SELECT f."c_0171" INTO c_0409
            FROM mrv."t_0012" f
            WHERE f.id = (p_0082->>'_')::UUID;

        WHEN '_' THEN
            
            c_0409 := NULL;

        WHEN '_' THEN
            c_0409 := (p_0082->>'_')::UUID;

        WHEN '_' THEN
            SELECT COALESCE(
                (SELECT cp."c_0171" FROM mrv."t_0001" cp
                 WHERE cp.id = (p_0082->>'_')::UUID),
                (SELECT f."c_0171" FROM mrv."t_0012" f
                 WHERE f.id = (p_0082->>'_')::UUID)
            ) INTO c_0409;

        ELSE
            RAISE EXCEPTION '_%_', p_0107;
    END CASE;

    RETURN c_0409;
END;
$$ LANGUAGE plpgsql STABLE SECURITY DEFINER
   SET search_path = '_';




CREATE OR REPLACE FUNCTION audit.f_0096()
RETURNS TRIGGER AS $$
DECLARE
    v_secret TEXT;
    v_payload TEXT;
BEGIN
    SELECT value INTO v_secret FROM audit.t_0046 WHERE key = '_';
    IF v_secret IS NULL THEN
        RAISE EXCEPTION '_';
    END IF;

    v_payload := jsonb_build_object(
        '_', NEW.id,
        '_', NEW.timestamp,
        '_', NEW.c_0533,
        '_', NEW.p_0001,
        '_', NEW.action,
        '_', NEW.c_0140
    )::text;

    NEW.c_0440 := encode(
        extensions.hmac(v_payload, v_secret, '_'),
        '_'
    );

    RETURN NEW;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER
   SET search_path = '_';




