CREATE OR REPLACE FUNCTION mrv.f_0001()
RETURNS TABLE (
    p_0004 uuid
)
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = mrv, auth, public
AS $$
DECLARE
    v_current_user_id uuid;
    v_supplier_id uuid;
BEGIN
    v_current_user_id := auth.f_0100();
    IF v_current_user_id IS NULL THEN
        RAISE EXCEPTION '_';
    END IF;

    v_supplier_id := (
        auth.f_0065()
        -> '_' -> '_' ->> 0
    )::uuid;

    IF v_supplier_id IS NULL THEN
        RAISE EXCEPTION '_';
    END IF;

    IF NOT EXISTS (
        SELECT 1
        FROM public.t_0091 s
        WHERE s.id = v_supplier_id
          AND s.ty_0034 = 'v1'
    ) THEN
        RAISE EXCEPTION '_';
    END IF;

    RETURN QUERY
    SELECT f.id
    FROM mrv."t_0012" f
    WHERE f."c_0171" = v_supplier_id;
END;
$$;

CREATE OR REPLACE FUNCTION mrv.f_0002(
    p_0027 uuid,
    p_0029 text,
    p_0076 uuid,
    p_0033 uuid[]
)
RETURNS TABLE(id uuid, "c_0359" uuid, "c_0182" uuid, "c_0092" timestamptz)
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = mrv, auth, public
AS $$
#variable_conflict use_column
DECLARE
    v_current_user_id uuid;
    v_facility_id uuid;
    v_link_id uuid;
BEGIN
    v_current_user_id := auth.f_0100();
    IF v_current_user_id IS NULL THEN
        RAISE EXCEPTION '_';
    END IF;

    
    BEGIN
        PERFORM p_0029::mrv."ty_0007";
    EXCEPTION WHEN invalid_text_representation THEN
        RAISE EXCEPTION '_%_', p_0029;
    END;

    
    IF NOT mrv.f_0112(p_0029, p_0027) THEN
        RAISE EXCEPTION '_';
    END IF;

    
    IF NOT EXISTS (
        SELECT 1 FROM mrv."t_0020"
        WHERE id = p_0076
          AND (
            ("c_0399" = p_0027 AND "c_0400" = p_0029::mrv."ty_0007")
            OR
            ("c_0454" = p_0027 AND "c_0455" = p_0029::mrv."ty_0007")
          )
    ) THEN
        RAISE EXCEPTION '_';
    END IF;

    
    IF p_0033 IS NULL OR array_length(p_0033, 1) IS NULL THEN
        RAISE EXCEPTION '_';
    END IF;

    FOREACH v_facility_id IN ARRAY p_0033
    LOOP
        
        IF NOT EXISTS (
            SELECT 1 FROM mrv."t_0010"
            WHERE id = v_facility_id
              AND "c_0171" = p_0027
              AND "c_0172" = p_0029::mrv."ty_0007"
        ) THEN
            RAISE EXCEPTION '_%_%_', v_facility_id, p_0027;
        END IF;

        
        IF EXISTS (
            SELECT 1 FROM mrv."t_0021"
            WHERE "c_0359" = p_0076 AND "c_0182" = v_facility_id
        ) THEN
            CONTINUE;
        END IF;

        
        INSERT INTO mrv."t_0021" (id, "c_0359", "c_0182", "c_0092")
        VALUES (gen_random_uuid(), p_0076, v_facility_id, NOW())
        RETURNING id INTO v_link_id;

        RETURN QUERY SELECT pf.id, pf."c_0359", pf."c_0182", pf."c_0092"
                     FROM mrv."t_0021" pf WHERE pf.id = v_link_id;
    END LOOP;
END;
$$;

CREATE OR REPLACE FUNCTION mrv.f_0014(
    p_0032 uuid,
    p_0038 uuid[]
)
RETURNS TABLE(id uuid, "c_0182" uuid, "c_0191" uuid, "c_0019" timestamp, "c_0020" uuid, "c_0092" timestamptz, "c_0524" timestamptz)
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = mrv, auth, public
AS $$
#variable_conflict use_column
DECLARE
    v_current_user_id uuid;
    v_facility_entity_type text;
    v_facility_entity_id uuid;
    v_farmer_id uuid;
    v_result_id uuid;
BEGIN
    v_current_user_id := auth.f_0100();
    IF v_current_user_id IS NULL THEN
        RAISE EXCEPTION '_';
    END IF;

    
    SELECT "c_0172"::text, "c_0171"
    INTO v_facility_entity_type, v_facility_entity_id
    FROM mrv."t_0010"
    WHERE id = p_0032;

    IF v_facility_entity_type IS NULL THEN
        RAISE EXCEPTION '_';
    END IF;

    
    IF NOT mrv.f_0112(v_facility_entity_type, v_facility_entity_id) THEN
        RAISE EXCEPTION '_';
    END IF;

    
    IF p_0038 IS NULL OR array_length(p_0038, 1) IS NULL THEN
        RAISE EXCEPTION '_';
    END IF;

    FOREACH v_farmer_id IN ARRAY p_0038
    LOOP
        INSERT INTO mrv."t_0011" (id, "c_0182", "c_0191", "c_0019", "c_0020", "c_0092", "c_0524")
        VALUES (gen_random_uuid(), p_0032, v_farmer_id, NOW(), v_current_user_id, NOW(), NOW())
        ON CONFLICT ("c_0182", "c_0191")
        DO UPDATE SET "c_0020" = v_current_user_id, "c_0524" = NOW()
        RETURNING id INTO v_result_id;

        RETURN QUERY SELECT ff.id, ff."c_0182", ff."c_0191", ff."c_0019",
                            ff."c_0020", ff."c_0092", ff."c_0524"
                     FROM mrv."t_0011" ff WHERE ff.id = v_result_id;
    END LOOP;
END;
$$;

CREATE OR REPLACE FUNCTION mrv.f_0015(
    p_0076 uuid,
    p_0113 uuid[]
)
RETURNS TABLE (
    id uuid,
    c_0362 uuid,
    p_0005 uuid,
    c_0021 timestamptz,
    c_0022 uuid,
    c_0094 timestamptz,
    c_0525 timestamptz
)
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER 
SET search_path = mrv, auth, public
AS $$
DECLARE
    v_reporting_entity_id uuid;
    v_reporting_entity_type text;
    v_current_user_id uuid;
    v_user_id uuid;
BEGIN
    v_current_user_id := auth.f_0100();
    IF v_current_user_id IS NULL THEN
        RAISE EXCEPTION '_';
    END IF;

    SELECT p."c_0399", p."c_0400"::text
    INTO v_reporting_entity_id, v_reporting_entity_type
    FROM mrv."t_0020" p
    WHERE p.id = p_0076;

    IF v_reporting_entity_id IS NULL THEN
        RAISE EXCEPTION '_';
    END IF;

    IF NOT auth.f_0122(v_reporting_entity_id, v_reporting_entity_type) THEN
        RAISE EXCEPTION '_';
    END IF;

    FOREACH v_user_id IN ARRAY p_0113
    LOOP
        RETURN QUERY
        INSERT INTO mrv."t_0022" (
            "c_0359", "c_0191", "c_0020", "c_0019", "c_0092", "c_0524"
        ) VALUES (
            p_0076, v_user_id, v_current_user_id, NOW(), NOW(), NOW()
        )
        ON CONFLICT ("c_0359", "c_0191")
        DO UPDATE SET
            "c_0020" = EXCLUDED."c_0020",
            "c_0524" = NOW()
        RETURNING
            "t_0022".id,
            "t_0022"."c_0359",
            "t_0022"."c_0191",
            "t_0022"."c_0019",
            "t_0022"."c_0020",
            "t_0022"."c_0092",
            "t_0022"."c_0524";
    END LOOP;
END;
$$;




CREATE OR REPLACE FUNCTION mrv.f_0016(
    p_0036 uuid[],
    p_0117 int
)
RETURNS TABLE (
    p_0004 uuid,
    c_0059 double precision,
    c_0055 jsonb
)
LANGUAGE plpgsql
STABLE
SECURITY DEFINER 
SET search_path = mrv, auth, public
AS $$
BEGIN
    IF array_length(p_0036, 1) IS NULL THEN
        RETURN;
    END IF;

    RETURN QUERY
    WITH dom_results AS (
        SELECT DISTINCT ON (dcr."c_0186")
            dcr."c_0186" AS p_0004,
            dcr."c_0319" / 1000.0 AS c_0059,
            dcr."c_0054" AS c_0055
        FROM mrv."t_0007" dcr
        WHERE dcr."c_0186" = ANY(p_0036)
            AND dcr."c_0056" = p_0117
            AND dcr."c_0319" > 0
        ORDER BY dcr."c_0186", dcr."c_0051" DESC
    ),
    soil_metrics AS (
        SELECT DISTINCT ON (fsm."c_0186")
            fsm."c_0186" AS p_0004,
            fsm.value AS c_0059,
            NULL::jsonb AS c_0055
        FROM mrv."t_0013" fsm
        WHERE fsm."c_0186" = ANY(p_0036)
            AND fsm."c_0355" = 'v1'
            AND fsm."c_0468" <= make_date(p_0117, 12, 31)
            AND fsm."c_0167" >= make_date(p_0117, 1, 1)
            AND fsm.value > 0
        ORDER BY fsm."c_0186", fsm."c_0468" DESC, fsm."c_0167" DESC
    ),
    all_farms AS (
        SELECT unnest(p_0036) AS p_0004
    )
    SELECT
        af.p_0004,
        COALESCE(dr.c_0059, sm.c_0059, 0.0)::double precision,
        COALESCE(dr.c_0055, sm.c_0055)
    FROM all_farms af
    LEFT JOIN dom_results dr ON dr.p_0004 = af.p_0004
    LEFT JOIN soil_metrics sm ON sm.p_0004 = af.p_0004 AND dr.p_0004 IS NULL;
END;
$$;

CREATE OR REPLACE FUNCTION mrv.f_0017(
    p_0073 uuid
)
RETURNS TABLE (
    id uuid,
    con_0119 uuid,
    c_0271 uuid,
    c_0470 text,
    c_0218 text,
    c_0493 int,
    c_0494 double precision,
    c_0126 double precision,
    c_0036 boolean[],
    c_0262 boolean,
    c_0123 boolean[],
    c_0264 boolean,
    c_0125 double precision,
    c_0263 boolean,
    c_0124 double precision,
    c_0265 boolean,
    c_0209 boolean[],
    c_0267 boolean,
    c_0211 double precision,
    c_0266 boolean,
    c_0210 double precision,
    c_0175 text,
    c_0411 jsonb,
    c_0189 uuid[],
    c_0094 timestamptz,
    c_0525 timestamptz
)
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = mrv, auth, public
AS $$
DECLARE
    v_current_user_id uuid;
    v_supplier_id uuid;
    v_plan RECORD;
BEGIN
    v_current_user_id := auth.f_0100();
    IF v_current_user_id IS NULL THEN
        RAISE EXCEPTION '_';
    END IF;

    IF p_0073 IS NULL THEN
        RAISE EXCEPTION '_';
    END IF;

    v_supplier_id := (
        auth.f_0065()
        -> '_' -> '_' ->> 0
    )::uuid;

    IF v_supplier_id IS NULL THEN
        RAISE EXCEPTION '_';
    END IF;

    IF NOT EXISTS (
        SELECT 1
        FROM public.t_0091 s
        WHERE s.id = v_supplier_id
          AND s.ty_0034 = 'v1'
    ) THEN
        RAISE EXCEPTION '_';
    END IF;

    SELECT cp.*
    INTO v_plan
    FROM mrv."t_0001" cp
    WHERE cp.id = p_0073
      AND cp."c_0171" = v_supplier_id;

    IF v_plan IS NULL THEN
        RAISE EXCEPTION '_';
    END IF;

    IF v_plan.c_0470 = 'v1' THEN
        RAISE EXCEPTION '_';
    END IF;

    IF v_plan.c_0470 = 'v1' THEN
        RETURN QUERY SELECT
            v_plan.id,
            v_plan."c_0171",
            v_plan."c_0270",
            v_plan.c_0470::text,
            v_plan."c_0217"::text,
            v_plan."c_0490",
            v_plan."c_0491",
            v_plan."c_0120",
            v_plan."c_0035",
            v_plan."c_0249",
            v_plan."c_0117",
            v_plan."c_0251",
            v_plan."c_0119",
            v_plan."c_0250",
            v_plan."c_0118",
            v_plan."c_0252",
            v_plan."c_0205",
            v_plan."c_0254",
            v_plan."c_0207",
            v_plan."c_0253",
            v_plan."c_0206",
            v_plan."c_0174",
            v_plan.c_0411,
            ARRAY(SELECT cpf."c_0186" FROM mrv."t_0002" cpf WHERE cpf."c_0057" = v_plan.id AND cpf."c_0186" IS NOT NULL),
            v_plan."c_0092",
            v_plan."c_0524";
        RETURN;
    END IF;

    UPDATE mrv."t_0001"
    SET c_0470 = 'v1',
        "c_0174" = NULL,
        "c_0524" = NOW()
    WHERE mrv."t_0001".id = p_0073
      AND mrv."t_0001"."c_0171" = v_supplier_id;

    RETURN QUERY SELECT
        cp.id,
        cp."c_0171",
        cp."c_0270",
        cp.c_0470::text,
        cp."c_0217"::text,
        cp."c_0490",
        cp."c_0491",
        cp."c_0120",
        cp."c_0035",
        cp."c_0249",
        cp."c_0117",
        cp."c_0251",
        cp."c_0119",
        cp."c_0250",
        cp."c_0118",
        cp."c_0252",
        cp."c_0205",
        cp."c_0254",
        cp."c_0207",
        cp."c_0253",
        cp."c_0206",
        cp."c_0174",
        cp.c_0411,
        ARRAY(SELECT cpf."c_0186" FROM mrv."t_0002" cpf WHERE cpf."c_0057" = cp.id AND cpf."c_0186" IS NOT NULL),
        cp."c_0092",
        cp."c_0524"
    FROM mrv."t_0001" cp
    WHERE cp.id = p_0073
      AND cp."c_0171" = v_supplier_id;
END;
$$;

CREATE OR REPLACE FUNCTION mrv.f_0027()
RETURNS integer
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = mrv, public
AS $$
DECLARE
    deleted_count integer;
BEGIN
    DELETE FROM mrv.t_0072
    WHERE c_0094 < now() - INTERVAL '1 day';

    GET DIAGNOSTICS deleted_count = ROW_COUNT;
    RETURN deleted_count;
END;
$$;

