        "c_0214", "c_0213"
    ) VALUES (
        p_0050, p_0026, p_0012, p_0094,
        p_0091, p_0092, p_0034, p_0042,
        v_current_user_id, p_0047
    );

    IF p_0063 THEN
        INSERT INTO audit.t_0096 (c_0533, p_0001, action, c_0140)
        VALUES (
            v_current_user_id,
            p_0026,
            '_',
            jsonb_build_object(
                '_', p_0012,
                '_', p_0034,
                '_', p_0092
            )
        );
    END IF;
END;
$$;

