        FROM public.t_0091 s
        WHERE s.id = v_supplier_id
          AND s.ty_0034 = 'v1'
    ) THEN
        RAISE EXCEPTION '_';
    END IF;

    RETURN QUERY
    SELECT
        cp.id,
        cp."c_0171",
        cp.c_0292,
        cp."c_0326",
        cp."c_0270",
        cp.c_0470::text,
        cp."c_0217"::text,
        cp."c_0490",
        cp."c_0491",
        cp."c_0120",
        cp."c_0035",
        cp."c_0249",
        cp."c_0117",
        cp."c_0251",
