        cp."c_0207",
        cp."c_0253",
        cp."c_0206",
        cp."c_0208"::text,
        cp."c_0174",
        cp.c_0411,
        ARRAY(
            SELECT cpf."c_0186"
            FROM mrv."t_0002" cpf
            WHERE cpf."c_0057" = cp.id
              AND cpf."c_0186" IS NOT NULL
        ),
        cp."c_0092",
        cp."c_0524",
        (
            SELECT jsonb_agg(jsonb_build_object(
                '_', f.id,
                '_', f.name,
                '_', CASE WHEN f."c_0353" IS NOT NULL THEN (
                    SELECT ST_Area(p.geometry::geography) / 10000.0
                    FROM mrv."Polygon" p
                    WHERE p.id = f."c_0353"
                ) END,
                '_', (
