                )
            ) ORDER BY f.id)
            FROM mrv."t_0002" cpf2
            JOIN mrv."t_0012" f ON f.id = cpf2."c_0186"
            WHERE cpf2."c_0057" = cp.id
        )
    FROM mrv."t_0001" cp
    WHERE cp.id = p_0073
      AND cp."c_0171" = v_supplier_id;
END;
$$;

