CREATE OR REPLACE FUNCTION mrv.f_0131(
    p_0078    uuid,
    p_0053 text,
    p_0104   uuid,
    p_0015  text
)
RETURNS TABLE (
    id            uuid,
    "c_0367"   uuid,
    "c_0236" text,
    c_0470        text,
    "c_0088" text,
    "c_0482"  uuid,
    "c_0092"   timestamptz,
    "c_0524"   timestamptz
)
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = mrv, auth, public
AS $$
#variable_conflict use_column
DECLARE
    v_proponent_id  uuid;
    v_status        text := '_';
BEGIN
    SELECT "c_0373"
    INTO v_proponent_id
    FROM mrv."t_0032"
    WHERE id = p_0078;

    IF NOT FOUND THEN
        RAISE EXCEPTION '_%_', p_0078;
    END IF;

    IF NOT auth.f_0120(v_proponent_id) THEN
        RAISE EXCEPTION '_';
    END IF;

    IF p_0053 NOT IN ('_', '_', '_') THEN
        RAISE EXCEPTION '_%_', p_0053;
    END IF;

    IF EXISTS (
        SELECT 1
        FROM mrv."t_0035"
        WHERE "c_0367" = p_0078
          AND "c_0088" = p_0015
    ) THEN
        v_status := '_';
    END IF;

    RETURN QUERY
    INSERT INTO mrv."t_0037" (
        "c_0367",
        "c_0236",
        "c_0470",
        "c_0482",
        "c_0088"
    )
    VALUES (
        p_0078,
        p_0053::mrv."ty_0027",
        v_status::mrv."ty_0026",
        p_0104,
        p_0015
    )
    RETURNING
        "t_0037".id,
        "t_0037"."c_0367",
        "t_0037"."c_0236"::text,
        "t_0037".c_0470::text,
        "t_0037"."c_0088",
        "t_0037"."c_0482",
        "t_0037"."c_0092",
        "t_0037"."c_0524";
END;
$$;








CREATE OR REPLACE FUNCTION mrv.f_0132(
    p_0078 uuid
)
RETURNS JSONB
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = mrv, auth, public
AS $$
BEGIN
    IF auth.f_0100() IS NULL THEN
        RAISE EXCEPTION '_';
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM mrv."t_0032" p
        WHERE p."id" = p_0078
    ) THEN
        RETURN NULL;
    END IF;

    IF NOT auth.f_0109(p_0078) THEN
        RAISE EXCEPTION '_';
    END IF;

    RETURN mrv.f_0135(p_0078);
END;
$$;

CREATE OR REPLACE FUNCTION mrv.f_0133()
RETURNS JSONB
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = mrv, auth, public
AS $$
BEGIN
    IF auth.f_0100() IS NULL THEN
        RAISE EXCEPTION '_';
    END IF;

    RETURN COALESCE(
        (
            SELECT jsonb_agg(mrv.f_0135(p."id") ORDER BY p."c_0092" DESC)
            FROM mrv."t_0032" p
            WHERE auth.f_0109(p."id")
        ),
        'null'::jsonb
    );
END;
$$;

CREATE OR REPLACE FUNCTION mrv.f_0134(
    p_0078 uuid,
    p_0035 uuid
)
RETURNS JSONB
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = mrv, auth, public
AS $$
BEGIN
    IF auth.f_0100() IS NULL THEN
        RAISE EXCEPTION '_';
    END IF;

    IF NOT auth.f_0109(p_0078) THEN
        RAISE EXCEPTION '_';
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM mrv."t_0032" p
        WHERE p."id" = p_0078
    ) THEN
        RAISE EXCEPTION '_';
    END IF;

    DELETE FROM mrv."t_0036"
    WHERE "c_0367" = p_0078
      AND "c_0186" = p_0035;

    UPDATE mrv."t_0032"
    SET "c_0524" = now()
    WHERE "id" = p_0078;

    RETURN mrv.f_0135(p_0078);
END;
$$;

CREATE OR REPLACE FUNCTION mrv.f_0135(
    p_0078 uuid
)
RETURNS JSONB
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = mrv, auth, public
AS $$
DECLARE
    v_result JSONB;
BEGIN
    SELECT jsonb_build_object(
        '_', p."id",
        '_', p."name",
        '_', p."c_0139",
        '_', p."c_0470"::text,
        '_', to_char(p."c_0097", '_'),
        '_', to_char(p."c_0096", '_'),
        '_', p."c_0092",
        '_', p."c_0524",
        '_', COALESCE(
            (
                SELECT jsonb_agg(
                    jsonb_build_object(
                        '_', cp."id",
                        '_', cp."c_0355"::text,
                        '_', cp."c_0255",
                        '_', cp."c_0179"
                    )
                    ORDER BY cp."c_0355"::text
                )
                FROM mrv."t_0034" cp
                WHERE cp."c_0367" = p."id"
            ),
            'null'::jsonb
        ),
        '_', COALESCE(
            (
                SELECT jsonb_agg(
                    jsonb_build_object(
                        '_', pf."id",
                        '_', pf."c_0186",
                        '_', f."name",
                        '_', pf."c_0476"
                    )
                    ORDER BY f."name"
                )
                FROM mrv."t_0036" pf
                JOIN mrv."t_0012" f ON f."id" = pf."c_0186"
                WHERE pf."c_0367" = p."id"
            ),
            'null'::jsonb
        )
    )
    INTO v_result
    FROM mrv."t_0032" p
    WHERE p."id" = p_0078;

    RETURN v_result;
END;
$$;

CREATE OR REPLACE FUNCTION mrv.f_0136(
    p_0078 uuid,
    p_0111 jsonb
)
RETURNS JSONB
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = mrv, auth, public
AS $$
DECLARE
    v_status_value text;
BEGIN
    IF auth.f_0100() IS NULL THEN
        RAISE EXCEPTION '_';
    END IF;

    IF NOT auth.f_0109(p_0078) THEN
        RAISE EXCEPTION '_';
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM mrv."t_0032" p
        WHERE p."id" = p_0078
    ) THEN
        RAISE EXCEPTION '_';
    END IF;

    IF p_0111 ? '_' AND p_0111->>'_' IS NOT NULL THEN
        v_status_value := p_0111->>'_';
        IF v_status_value NOT IN ('_', '_', '_', '_') THEN
            RAISE EXCEPTION '_%_', v_status_value;
        END IF;
    END IF;

    UPDATE mrv."t_0032"
    SET
        "name" = CASE WHEN p_0111 ? '_' THEN p_0111->>'_' ELSE "name" END,
        "c_0139" = CASE WHEN p_0111 ? '_' THEN p_0111->>'_' ELSE "c_0139" END,
        "c_0470" = CASE WHEN p_0111 ? '_' AND p_0111->>'_' IS NOT NULL
                        THEN (p_0111->>'_')::mrv."ty_0029"
                        ELSE "c_0470" END,
        "c_0097" = CASE WHEN p_0111 ? '_'
                                      THEN (p_0111->>'_')::date
                                      ELSE "c_0097" END,
        "c_0096" = CASE WHEN p_0111 ? '_'
                                    THEN (p_0111->>'_')::date
                                    ELSE "c_0096" END,
        "c_0524" = now()
    WHERE "id" = p_0078;

    RETURN mrv.f_0135(p_0078);
END;
$$;

CREATE OR REPLACE FUNCTION mrv.f_0137(
    p_0078 uuid,
    p_0075 jsonb
)
RETURNS JSONB
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = mrv, auth, public
AS $$
DECLARE
    v_pool jsonb;
    v_pool_type text;
    v_is_included boolean;
    v_justification text;
    v_all_pool_types mrv."ty_0025"[] := ARRAY[
        '_',
        '_',
        '_',
        '_',
        '_',
        '_'
    ]::mrv."ty_0025"[];
    v_provided_types text[];
BEGIN
    IF auth.f_0100() IS NULL THEN
        RAISE EXCEPTION '_';
    END IF;

    IF NOT auth.f_0109(p_0078) THEN
        RAISE EXCEPTION '_';
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM mrv."t_0032" p
        WHERE p."id" = p_0078
    ) THEN
        RAISE EXCEPTION '_';
    END IF;

    SELECT array_agg(pool->>'_')
    INTO v_provided_types
    FROM jsonb_array_elements(p_0075) AS pool;

    IF (
        SELECT count(*)
        FROM unnest(v_all_pool_types) AS required_type
        WHERE required_type::text != ALL(COALESCE(v_provided_types, ARRAY[]::text[]))
    ) > 0 THEN
        RAISE EXCEPTION '_';
    END IF;

    FOR v_pool IN SELECT * FROM jsonb_array_elements(p_0075)
    LOOP
        v_pool_type := v_pool->>'_';
        v_is_included := (v_pool->>'_')::boolean;
        v_justification := v_pool->>'_';

        IF v_pool_type = '_' AND NOT v_is_included THEN
            RAISE EXCEPTION '_';
        END IF;

        IF NOT v_is_included AND v_justification IS NULL THEN
            RAISE EXCEPTION '_%_', v_pool_type;
        END IF;
    END LOOP;

    DELETE FROM mrv."t_0034"
    WHERE "c_0367" = p_0078;

    INSERT INTO mrv."t_0034" (
        "c_0367",
        "c_0355",
        "c_0255",
        "c_0179"
    )
    SELECT
        p_0078,
        (pool->>'_')::mrv."ty_0025",
        (pool->>'_')::boolean,
        pool->>'_'
    FROM jsonb_array_elements(p_0075) AS pool;

    UPDATE mrv."t_0032"
    SET "c_0524" = now()
    WHERE "id" = p_0078;

    RETURN mrv.f_0135(p_0078);
END;
$$;


CREATE OR REPLACE FUNCTION mrv.f_0138(
    p_0026 uuid,
    p_0012 int
)
RETURNS TABLE (
    p_0004 uuid,
    c_0190 text,
    c_0089 text,
    c_0427 text,
    c_0277 text,
    c_0161 double precision,
    c_0164 double precision,
    c_0162 double precision,
    c_0163 double precision,
    c_0112 double precision,
    c_0115 double precision,
    c_0113 double precision,
    c_0114 double precision,
    c_0320 double precision,
    c_0515 double precision,
    c_0160 text,
    c_0052 timestamptz,
    c_0055 jsonb
)
LANGUAGE plpgsql
STABLE
SECURITY INVOKER
AS $$
BEGIN
    RETURN QUERY
    SELECT
        f.id AS p_0004,
        f.name AS c_0190,
        f."ty_0003"::text AS c_0089,
        f."ty_0016"::text AS c_0427,
        f."ty_0013"::text AS c_0277,
        d."c_0156" AS c_0161,
        d."c_0159" AS c_0164,
        d."c_0157" AS c_0162,
        d."c_0158" AS c_0163,
        d."c_0108" AS c_0112,
        d."c_0111" AS c_0115,
        d."c_0109" AS c_0113,
        d."c_0110" AS c_0114,
        d."c_0319" AS c_0320,
        d."c_0507" AS c_0515,
        d."c_0155"::text AS c_0160,
        d."c_0051" AS c_0052,
        d."c_0054" AS c_0055
    FROM mrv."t_0012" f
    JOIN mrv."t_0007" d
        ON d."c_0186" = f.id
        AND d."c_0056" = p_0012
    WHERE f."c_0171" IN (
        SELECT ur.p_0123
        FROM public.t_0093 ur
        JOIN public.t_0090 sf ON sf.p_0005 = ur.p_0005
        JOIN public.t_0049 es ON es.p_0121 = sf.p_0121
        WHERE es.p_0001 = p_0026
    )
    ORDER BY f.name;
END;
$$;




CREATE OR REPLACE FUNCTION mrv.f_0141(
    p_0052 uuid
)
RETURNS TABLE (
    c_0437 text,
    c_0128 jsonb
)
LANGUAGE plpgsql
STABLE
SECURITY INVOKER
AS $$
DECLARE
    v_supplier_id uuid;
BEGIN
    SELECT vpi."c_0482"
    INTO v_supplier_id
    FROM mrv."t_0037" vpi
    WHERE vpi.id = p_0052;

    
    RETURN QUERY
    SELECT
        '_'::text AS c_0437,
        (
            SELECT jsonb_build_object(
                '_', COALESCE(jsonb_agg(
                    jsonb_build_object(
                        '_', vp.id,
                        '_', vp.name,
                        '_', vp.c_0139,
                        '_', vp.c_0470,
                        '_', vp."c_0097",
                        '_', vp."c_0096",
                        '_', jsonb_build_object(
                            '_', vp."c_0366",
                            '_', vp."c_0041",
                            '_', vp."c_0005",
                            '_', vp."c_0287",
                            '_', vp."c_0316",
                            '_', vp."c_0341"
                        ),
                        '_', (
                            SELECT COALESCE(jsonb_agg(
                                jsonb_build_object(
                                    '_', cp."c_0355",
                                    '_', cp."c_0255",
                                    '_', cp."c_0179"
                                )
                            ), 'null'::jsonb)
                            FROM mrv."t_0034" cp
                            WHERE cp."c_0367" = vp.id
                        ),
                        '_', (
                            SELECT COALESCE(jsonb_agg(pf."c_0186"), 'null'::jsonb)
                            FROM mrv."t_0036" pf
                            WHERE pf."c_0367" = vp.id
                              AND pf."c_0235" = p_0052
                        )
                    )
                ), 'null'::jsonb)
            )
            FROM mrv."t_0032" vp
            WHERE vp.id IN (
                SELECT DISTINCT pf2."c_0367"
                FROM mrv."t_0036" pf2
                WHERE pf2."c_0235" = p_0052
            )
        ) AS c_0128;

    
    RETURN QUERY
    SELECT
        '_'::text AS c_0437,
        (
            SELECT jsonb_build_object(
                '_', COALESCE(jsonb_agg(
                    jsonb_build_object(
                        '_', f.id,
                        '_', f.name,
                        '_', f."ty_0003",
                        '_', f."ty_0016",
                        '_', f."ty_0013",
                        '_', CASE
                            WHEN p.geometry IS NOT NULL
                            THEN ST_AsGeoJSON(p.geometry)::jsonb
                        END,
                        '_', (
                            SELECT pf."c_0476"
                            FROM mrv."t_0036" pf
                            WHERE pf."c_0186" = f.id
                              AND pf."c_0235" = p_0052
                            ORDER BY pf."c_0367"
                            LIMIT 1
                        )
                    )
                    ORDER BY f.id
                ), 'null'::jsonb)
            )
            FROM mrv."t_0012" f
            LEFT JOIN mrv."Polygon" p ON p.id = f."c_0353"
            WHERE f.id IN (
                SELECT pf."c_0186"
                FROM mrv."t_0036" pf
                WHERE pf."c_0235" = p_0052
            )
        ) AS c_0128;

    
    
    RETURN QUERY
    SELECT
        '_'::text AS c_0437,
        (
            SELECT jsonb_build_object(
                '_', COALESCE(jsonb_agg(
                    jsonb_build_object(
                        '_', cp.id,
                        '_', cp.c_0470,
                        '_', cp."c_0217",
                        '_', cp."c_0490",
                        '_', cp."c_0491",
                        '_', cp."c_0120",
                        '_', cp."c_0121",
                        '_', cp."c_0208",
                        '_', cp.c_0411,
                        '_', (
                            SELECT COALESCE(jsonb_agg(cpf."c_0186"), 'null'::jsonb)
                            FROM mrv."t_0002" cpf
                            WHERE cpf."c_0057" = cp.id
                        ),
                        '_', cp."c_0092"
                    )
                ), 'null'::jsonb)
            )
            FROM mrv."t_0001" cp
            WHERE cp."c_0171" = v_supplier_id
              AND cp.c_0470 = 'v1'
        ) AS c_0128;

    
    RETURN QUERY
    SELECT
        '_'::text AS c_0437,
        (
            SELECT jsonb_build_object(
                '_', COALESCE(jsonb_agg(
                    jsonb_build_object(
                        '_', d."c_0186",
                        '_', d."c_0056",
                        '_', d."c_0319",
                        '_', d."c_0507",
                        '_', d."c_0156",
                        '_', d."c_0159",
                        '_', d."c_0157",
                        '_', d."c_0158",
                        '_', d."c_0108",
                        '_', d."c_0111",
                        '_', d."c_0109",
                        '_', d."c_0110",
                        '_', d."c_0155",
                        '_', d."c_0051"
                    )
                    ORDER BY d."c_0186", d."c_0056"
                ), 'null'::jsonb),
                '_', (
                    SELECT COALESCE(jsonb_agg(
                        jsonb_build_object(
                            '_', sub."c_0186",
                            '_', sub.total_net,
                            '_', sub.latest_carbon,
                            '_', sub.year_count,
                            '_', sub.first_year,
                            '_', sub.last_year
                        )
                    ), 'null'::jsonb)
                    FROM (
                        SELECT
                            d2."c_0186",
                            SUM(d2."c_0319") AS total_net,
                            (ARRAY_AGG(d2."c_0507" ORDER BY d2."c_0056" DESC))[1] AS latest_carbon,
                            COUNT(*) AS year_count,
                            MIN(d2."c_0056") AS first_year,
                            MAX(d2."c_0056") AS last_year
                        FROM mrv."t_0007" d2
                        WHERE d2."c_0186" IN (
                            SELECT pf."c_0186"
                            FROM mrv."t_0036" pf
                            WHERE pf."c_0235" = p_0052
                        )
                        GROUP BY d2."c_0186"
                    ) sub
                )
            )
            FROM mrv."t_0007" d
            WHERE d."c_0186" IN (
                SELECT pf."c_0186"
                FROM mrv."t_0036" pf
                WHERE pf."c_0235" = p_0052
            )
        ) AS c_0128;

    
    RETURN QUERY
    SELECT
        '_'::text AS c_0437,
        (
            SELECT jsonb_build_object(
                '_', COALESCE(jsonb_agg(
                    jsonb_build_object(
                        '_', c.id,
                        '_', c."c_0186",
                        '_', c."c_0101",
                        '_', c."c_0349",
                        '_', c."c_0221",
                        '_', c."c_0248",
                        '_', c."c_0497",
                        '_', c.c_0470,
                        '_', jsonb_build_object(
                            '_', s.id,
                            '_', s.name,
                            '_', s."c_0468",
                            '_', s."c_0167"
                        )
                    )
                    ORDER BY c."c_0186", c."c_0349"
                ), 'null'::jsonb)
            )
            FROM mrv."t_0006" c
            JOIN mrv."t_0024" s ON s.id = c."c_0434"
            WHERE c."c_0186" IN (
                SELECT pf."c_0186"
                FROM mrv."t_0036" pf
                WHERE pf."c_0235" = p_0052
            )
        ) AS c_0128;

    
    RETURN QUERY
    SELECT
        '_'::text AS c_0437,
        (
            SELECT jsonb_build_object(
                '_', COALESCE(jsonb_agg(
                    jsonb_build_object(
                        '_', sr.id,
                        '_', sr."c_0186",
                        '_', sr."c_0420",
                        '_', (
                            SELECT COALESCE(jsonb_agg(
                                jsonb_build_object(
                                    '_', sm.c_0337,
                                    '_', sm.value
                                )
                            ), 'null'::jsonb)
                            FROM mrv."t_0025" sm
                            WHERE sm."c_0450" = sr.id
                        )
                    )
                    ORDER BY sr."c_0186", sr."c_0420"
                ), 'null'::jsonb)
            )
            FROM mrv."t_0026" sr
            WHERE sr."c_0186" IN (
                SELECT pf."c_0186"
                FROM mrv."t_0036" pf
                WHERE pf."c_0235" = p_0052
            )
        ) AS c_0128;

    
    
    RETURN QUERY
    SELECT
        '_'::text AS c_0437,
        (
            SELECT jsonb_build_object(
                '_', COALESCE(jsonb_agg(
                    jsonb_build_object(
                        '_', s.id,
                        '_', s.name,
                        '_', s."c_0468",
                        '_', s."c_0167"
                    )
                    ORDER BY s."c_0468"
                ), 'null'::jsonb)
            )
            FROM mrv."t_0024" s
            WHERE s."c_0171" = v_supplier_id
        ) AS c_0128;
END;
$$;

CREATE OR REPLACE FUNCTION mrv.f_0142(
    p_0050 uuid
)
RETURNS TABLE(id uuid, "c_0482" uuid, "c_0169" uuid, "c_0453" text, "c_0456" uuid, "c_0101" text, "c_0379" double precision, "c_0485" date, "c_0093" uuid, "c_0092" timestamptz, "c_0524" timestamptz)
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER 
SET search_path = mrv, auth, public
AS $$
#variable_conflict use_column
DECLARE
    v_current_user_id uuid;
    v_existing RECORD;
BEGIN
    v_current_user_id := auth.f_0100();
    IF v_current_user_id IS NULL THEN
        RAISE EXCEPTION '_';
    END IF;

    PERFORM pg_advisory_xact_lock(hashtext('_' || p_0050::text));

    SELECT *
    INTO v_existing
    FROM mrv."t_0027"
    WHERE id = p_0050;

    IF v_existing IS NULL THEN
        RAISE EXCEPTION '_';
    END IF;

    IF NOT auth.f_0117(p_0104 => v_existing."c_0482") THEN
        RAISE EXCEPTION '_';
    END IF;

    DELETE FROM mrv."t_0027" WHERE id = p_0050;

    IF NOT FOUND THEN
        RAISE EXCEPTION '_%_', p_0050;
    END IF;

    RETURN QUERY SELECT
        v_existing.id,
        v_existing."c_0482",
        v_existing."c_0169",
        v_existing."c_0453"::text,
        v_existing."c_0456",
        v_existing."c_0101"::text,
        v_existing."c_0379",
        v_existing."c_0485",
        v_existing."c_0093",
        v_existing."c_0092",
        v_existing."c_0524";
END;
$$;

CREATE OR REPLACE FUNCTION mrv.f_0143(
    p_0026 uuid,
    p_0117 int
)
RETURNS TABLE (
    c_0031 numeric,
    c_0310 numeric,
    c_0304 numeric,
    c_0471 numeric,
    c_0050 jsonb,
    c_0048 jsonb,
    c_0519 jsonb
)
LANGUAGE plpgsql
STABLE
SECURITY DEFINER 
SET search_path = mrv, auth, public
AS $$
#variable_conflict use_column
DECLARE
    v_current_user_id uuid;
BEGIN
    v_current_user_id := auth.f_0100();
    IF v_current_user_id IS NULL THEN
        RAISE EXCEPTION '_';
    END IF;

    IF NOT auth.f_0117(p_0026 => p_0026) THEN
        RAISE EXCEPTION '_';
    END IF;

    IF p_0117 IS NULL THEN
        RAISE EXCEPTION '_';
    END IF;

    IF p_0117 < 2000 OR p_0117 > EXTRACT(YEAR FROM NOW())::int + 5 THEN
        RAISE EXCEPTION '_%_', p_0117;
    END IF;

    RETURN QUERY
    WITH t_0049 AS (
        SELECT s.id AS p_0121, s.name AS c_0484
        FROM public.t_0049 es
        JOIN public.t_0091 s ON s.id = es.p_0121
        WHERE es.p_0001 = p_0026
    ),
    enterprise_farms AS (
        SELECT farm.id AS p_0004, farm."c_0171" AS con_0119, p.geometry,
               ST_Area(p.geometry::geography) / 10000 AS c_0017
        FROM mrv."t_0012" farm
        JOIN mrv."Polygon" p ON p.id = farm."c_0353"
        WHERE farm."c_0171" IN (SELECT p_0121 FROM t_0049)
        UNION
        
        SELECT farm.id, farm."c_0171", p.geometry,
               ST_Area(p.geometry::geography) / 10000
        FROM mrv."t_0012" farm
        JOIN mrv."Polygon" p ON p.id = farm."c_0353"
        JOIN public.t_0090 sf ON sf.p_0005 = farm."c_0171"
        JOIN t_0049 es ON es.p_0121 = sf.p_0121
    ),
    farm_supplier_mapping AS (
        SELECT ef.p_0004, ef.con_0119 AS p_0121
        FROM enterprise_farms ef
        WHERE ef.con_0119 IN (SELECT p_0121 FROM t_0049)
        UNION
        SELECT ef.p_0004, sf.p_0121
        FROM enterprise_farms ef
        JOIN public.t_0090 sf ON sf.p_0005 = ef.con_0119
    ),
    harvest_data AS (
        SELECT
            hr."c_0508",
            c."c_0101"::text AS c_0104,
            ef.p_0004,
            ef.con_0119,
            ef.c_0017
        FROM mrv."t_0016" hr
        JOIN mrv."t_0006" c ON c.id = hr."c_0116"
        JOIN enterprise_farms ef ON ef.p_0004 = c."c_0186"
        WHERE c.c_0470 = 'v1'
            AND c."c_0221" >= make_date(p_0117, 1, 1)
            AND c."c_0221" < make_date(p_0117 + 1, 1, 1)
            AND hr."c_0508" IS NOT NULL
            AND hr."c_0508" > 0
            AND ef.c_0017 > 0
    ),
    yield_per_ha_data AS (
        SELECT
            p_0004,
            con_0119,
            c_0104,
            "c_0508",
            c_0017,
            ("c_0508" / c_0017) AS yield_per_ha
        FROM harvest_data
    ),
    overall_stats AS (
        SELECT
            AVG(yield_per_ha)::numeric    AS c_0031,
            MIN(yield_per_ha)::numeric    AS c_0310,
            MAX(yield_per_ha)::numeric    AS c_0304,
            STDDEV(yield_per_ha)::numeric AS c_0471
        FROM yield_per_ha_data
    ),
    by_supplier_agg AS (
        SELECT
            es.p_0121,
            es.c_0484,
            AVG(yphd.yield_per_ha)::numeric AS c_0031,
            COUNT(DISTINCT fsm.p_0004) AS c_0188
        FROM t_0049 es
        JOIN farm_supplier_mapping fsm ON fsm.p_0121 = es.p_0121
        JOIN yield_per_ha_data yphd ON yphd.p_0004 = fsm.p_0004
        GROUP BY es.p_0121, es.c_0484
    ),
    by_supplier_json AS (
        SELECT COALESCE(jsonb_agg(
            jsonb_build_object(
                '_', p_0121,
                '_', c_0484,
                '_', c_0031,
                '_', c_0188
            )
        ), 'null'::jsonb) AS c_0409
        FROM by_supplier_agg
    ),
    crop_area AS (
        SELECT c_0104, SUM(c_0017)::numeric AS c_0017
        FROM (SELECT DISTINCT c_0104, p_0004, c_0017 FROM yield_per_ha_data) deduped
        GROUP BY c_0104
    ),
    by_crop_agg AS (
        SELECT
            yphd.c_0104,
            AVG(yphd.yield_per_ha)::numeric AS c_0031,
            SUM(yphd."c_0508")::numeric AS c_0517,
            ca.c_0017
        FROM yield_per_ha_data yphd
        JOIN crop_area ca ON ca.c_0104 = yphd.c_0104
        GROUP BY yphd.c_0104, ca.c_0017
    ),
    by_crop_json AS (
        SELECT COALESCE(jsonb_agg(
            jsonb_build_object(
                '_', c_0104,
                '_', c_0031,
                '_', c_0517,
                '_', c_0017
            )
        ), 'null'::jsonb) AS c_0409
        FROM by_crop_agg
    ),
    trend_years AS (
        SELECT generate_series(p_0117 - 4, p_0117) AS yr
    ),
    trend_data AS (
        SELECT
            ty.yr,
            AVG(
                CASE
                    WHEN hr_trend."c_0508" IS NOT NULL
                         AND hr_trend."c_0508" > 0
                         AND ef_trend.c_0017 > 0
                    THEN hr_trend."c_0508" / ef_trend.c_0017
                    ELSE NULL
                END
            )::numeric AS c_0031
        FROM trend_years ty
        LEFT JOIN mrv."t_0006" c_trend ON
            c_trend.c_0470 = 'v1'
            AND c_trend."c_0221" >= make_date(ty.yr, 1, 1)
            AND c_trend."c_0221" < make_date(ty.yr + 1, 1, 1)
            AND c_trend."c_0186" IN (SELECT p_0004 FROM enterprise_farms)
        LEFT JOIN mrv."t_0016" hr_trend ON hr_trend."c_0116" = c_trend.id
        LEFT JOIN enterprise_farms ef_trend ON ef_trend.p_0004 = c_trend."c_0186"
        GROUP BY ty.yr
        ORDER BY ty.yr
    ),
    trend_json AS (
        SELECT COALESCE(jsonb_agg(
            jsonb_build_object(
                '_', yr,
                '_', c_0031
            )
            ORDER BY yr
        ), 'null'::jsonb) AS c_0409
        FROM trend_data
    )
    SELECT
        os.c_0031,
        os.c_0310,
        os.c_0304,
        os.c_0471,
        bsj.c_0409 AS c_0050,
        bcj.c_0409 AS c_0048,
        tj.c_0409  AS c_0519
    FROM overall_stats os
    CROSS JOIN by_supplier_json bsj
    CROSS JOIN by_crop_json bcj
    CROSS JOIN trend_json tj;
END;
$$;




